-- ----------------------------
-- Table structure for dht
-- ----------------------------
DROP TABLE IF EXISTS `dht`;
CREATE TABLE `dht`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `suhu` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `kelembapan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `status` int NULL DEFAULT 0 COMMENT 'status kipas. 0=tidak menyala, 1 menyala',
  `create_date` datetime NULL DEFAULT NULL,
  `update _date` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2032 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

