-- ----------------------------
-- Table structure for mq
-- ----------------------------
DROP TABLE IF EXISTS `mq`;
CREATE TABLE `mq`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `status` int NULL DEFAULT 0 COMMENT '0 = tidak terdeteksi, 1 = terdetesi',
  `create_date` datetime NULL DEFAULT NULL,
  `update_date` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2032 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

